/** Review one frozen pending action with the fixed policy and current LLM route. */
async function classifyRisk(
  ctx: Context,
  agent: Agent,
  exec: ToolExecution,
  signal: AbortSignal,
): Promise<AutoReviewDecision> {
  const cwd = await ctx.workingDirectory.ensure(agent, signal)
  const snapshot = snapshotAutoReview(agent, exec, cwd)
  // This review prompt is sent only through ctx.llm.stream and never enters a Session log.
  const options: GenerateOptions = deepFreeze({
    provider: snapshot.provider,
    model: snapshot.model,
    system: REVIEW_POLICY,
    messages: [{
      role: 'user',
      content: [{ type: 'text', text: reviewUserText(snapshot) }],
    }],
    temperature: 0,
    signal,
  })
  return readDecision(ctx.llm.stream(options))
}

/** Snapshot, capture, and comparison bounds. Invalid values fail plugin load. */
export interface Config {
  /** Milliseconds one git command may run before the turn's record is abandoned. */
  timeoutMs: number
  /** Bytes of git output retained per command; a larger diff listing abandons the record. */
  outputMaxBytes: number
  /** Maximum files carried by one summary; `total` still reports the complete count. */
  maxFiles: number
  /**
   * Bytes a file may hold to be captured around a file-tool edit or read from a snapshot for its comparison.
   * A larger file gets no comparison; one captured around a file-tool edit is also listed without counts.
   */
  maxFileBytes: number
  /** Milliseconds a line comparison may run before it degrades to whole-file replacement. */
  diffTimeoutMs: number
}

/** Schemastery validation for {@link Config}. */
export const Config: z<Config> = z.object({
  timeoutMs: z.number().default(30_000),
  outputMaxBytes: z.number().default(8 * 1024 * 1024),
  maxFiles: z.number().default(500),
  maxFileBytes: z.number().default(2 * 1024 * 1024),
  diffTimeoutMs: z.number().default(100),
})

/** Default per-string and per-key cap applied to every bounded projected payload. */
export const MAX_STRING_BYTES = 8 * 1024

/** Default cap on one projected event's serialized bytes, newline included; the terminal `final` is exempt. */
export const MAX_EVENT_BYTES = 32 * 1024
